import React from "react";
import Header from "./Header";
import Footer from "./Footer";
import "../styles/main.css";

const ExtraCurricular = () => {
  return (
    <>
      
      <main className="main-container">
        <div className="two-column">
          <div className="left-column">
            <h2>Extra Curricular</h2>
            <div className="points-box">
              <p>Foreign Languages</p>
              <p>Ethics and Personality Development</p>
              <p>Sports</p>
              <p>Music & Dance</p>
              <p>Art & Craft</p>
              <p>Tour & Trips</p>
            </div>
          </div>
          <div className="right-column">
            <h2>Extra Curricular</h2>
            <p>"Every child is an artist. The problem is how to remain an artist once we grow up." – Pablo Picasso</p>
            <p>"A Picture is a poem without words." – Horace</p>
            <h3>Art Activities</h3>
            <p>Paint with Water colours, Crayon, Pencil Colours, Block Painting, Thread Painting, etc.</p>
            <h3>Craft Activities</h3>
            <p>Pot Making, Decoration with colours and papers, Purse making with waste material, Origami, etc. (See Pictures in Gallery)</p>
          </div>
        </div>
      </main>
      
    </>
  );
};

export default ExtraCurricular;
